(() => {
  const cards = [...document.querySelectorAll('.credential')];
  const filters = [...document.querySelectorAll('[data-filter]')];
  const search = document.querySelector('#certificate-search');
  const count = document.querySelector('#certificate-count');
  const more = document.querySelector('.archive-more');
  let category = 'All';
  let expanded = false;
  function updateArchive() {
    const query = search.value.trim().toLowerCase();
    const matches = cards.filter(card => (category === 'All' || card.dataset.category === category) && card.dataset.search.includes(query));
    const limit = expanded ? matches.length : 8;
    cards.forEach(card => { card.hidden = true; });
    matches.slice(0, limit).forEach(card => { card.hidden = false; });
    count.textContent = `Showing ${Math.min(limit, matches.length)} of ${matches.length} certificates`;
    document.querySelector('#certificate-empty').hidden = matches.length !== 0;
    more.hidden = matches.length <= 8;
    more.setAttribute('aria-expanded', String(expanded));
    more.firstChild.textContent = expanded ? 'Show fewer certificates ' : `Explore all ${matches.length} certificates `;
    more.querySelector('span').textContent = expanded ? '↑' : '↓';
  }
  filters.forEach(button => button.addEventListener('click', () => {
    category = button.dataset.filter;
    expanded = false;
    filters.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
    updateArchive();
  }));
  search.addEventListener('input', () => { expanded = false; updateArchive(); });
  more.addEventListener('click', () => {
    const firstHidden = cards.find(card => card.hidden);
    expanded = !expanded;
    updateArchive();
    if (!expanded) { document.querySelector('.certificate-tools').scrollIntoView({block:'start', behavior:'instant'}); more.focus({preventScroll:true}); return; }
    firstHidden?.querySelector('button').focus({preventScroll:true});
  });
  const dialog = document.querySelector('#certificate-dialog');
  document.querySelectorAll('[data-certificate]').forEach(button => button.addEventListener('click', () => {
    const item = certificateData[Number(button.dataset.certificate)];
    document.querySelector('#certificate-dialog-title').textContent = item.title;
    document.querySelector('#certificate-dialog-issuer').textContent = item.issuer;
    const image = document.querySelector('#certificate-dialog-image');
    image.src = item.image;
    image.alt = `${item.title} certificate awarded to Rajenthirakumar Abishek`;
    document.querySelector('#certificate-dialog-pdf').href = item.pdf;
    const verify = document.querySelector('#certificate-dialog-verify');
    verify.hidden = !item.verify;
    if (item.verify) verify.href = item.verify; else verify.removeAttribute('href');
    dialog.showModal();
  }));
  dialog.querySelector('button').addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', event => {
    const bounds = dialog.getBoundingClientRect();
    if (event.target === dialog && (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom)) dialog.close();
  });
  updateArchive();
})();
